#include <iostream>
#include <stdexcept>
class Account {
public:
    explicit Account(int initial_cents = 0) : balance_(initial_cents) {
        if (initial_cents < 0) throw std::invalid_argument("negative opening balance");
    }
    bool deposit(int cents) { if (cents <= 0) return false; balance_ += cents; return true; }
    bool withdraw(int cents) { if (cents <= 0 || cents > balance_) return false; balance_ -= cents; return true; }
    int balance() const { return balance_; }
private: int balance_;
};
int main() { Account account{1000}; account.deposit(250); account.withdraw(300); std::cout << account.balance() << " cents\n"; }
